:60,"durationStepId":"step-5"},{"id":"activity-step-7","kind":"heating","estimatedMinutes":null,"durationStepId":"step-8","after":"activity-step-5"},{"id":"activity-step-10","kind":"passive","estimatedMinutes":20,"durationStepId":"step-10","after":"activity-step-7"}],"suppressedStepIds":["serve"],"review":{"dishSequence":["step-1","step-2","step-3","step-4","step-5","step-6","step-7","step-8","step-9","step-10","serve"]}}}$friedTurkey$::jsonb $$;
